(38)\quad \(\left\{\begin{aligned}
\uline{b}\circ p_2&=\uline{s}\circ\uline{b'} &&\text{i.e. le carré}\\[5em]
p_1\circ p_2&=p_1\circ\uline{s'} &&\text{i.e. le carré}
\end{aligned}\right.\)

